import redis, time, sys

SRC = redis.Redis(port=6379, decode_responses=False)
DST = redis.Redis(port=6380, decode_responses=False)

now_ms = int(time.time()*1000)

def src_db(n): return redis.Redis(port=6379, db=n, decode_responses=False)
def dst_db(n): return redis.Redis(port=6380, db=n, decode_responses=False)

stats = {}

def migrate_db(n):
    s = src_db(n); d = dst_db(n)
    keys = s.keys('*')
    for key in keys:
        t = s.type(key)
        t = t.decode()
        # ---- capture key-level expiry (absolute ms) ----
        pexp = s.execute_command('PEXPIRETIME', key)
        # ---- value ----
        if t == 'string':
            val = s.get(key)
            d.set(key, val)
        elif t == 'list':
            elems = s.lrange(key, 0, -1)
            if elems: d.rpush(key, *elems)
        elif t == 'set':
            members = s.smembers(key)
            if members: d.sadd(key, *members)
        elif t == 'zset':
            flat = s.execute_command('ZRANGE', key, 0, -1, 'WITHSCORES')
            args = []
            for i in range(0, len(flat), 2):
                args.append(flat[i+1]); args.append(flat[i])
            if args: d.execute_command('ZADD', key, *args)
        elif t == 'hash':
            h = s.hgetall(key)
            if h: d.hset(key, mapping=h)
            # ---- hash field-level expiry ----
            fields = list(h.keys())
            if fields:
                exps = s.execute_command('HPEXPIRETIME', key, 'FIELDS', len(fields), *fields)
                pairs = [(f, e) for f, e in zip(fields, exps) if e not in (-1, -2)]
                for f, e in pairs:
                    d.execute_command('HPEXPIREAT', key, e, 'FIELDS', 1, f)
        elif t == 'stream':
            migrate_stream(s, d, key)
        else:
            raise RuntimeError("unknown type %s for %r" % (t, key))
        # ---- apply key-level TTL ----
        if pexp not in (-1, -2):
            d.execute_command('PEXPIREAT', key, pexp)
        stats[t] = stats.get(t, 0) + 1

def migrate_stream(s, d, key):
    info = s.xinfo_stream(key)
    entries = s.xrange(key, '-', '+')
    for eid, fields in entries:
        args = []
        for k, v in fields.items():
            args.append(k); args.append(v)
        d.execute_command('XADD', key, eid, *args)
    # set stream metadata
    d.execute_command('XSETID', key, info['last-generated-id'],
                      'ENTRIESADDED', info['entries-added'],
                      'MAXDELETEDID', info['max-deleted-entry-id'])
    for g in s.xinfo_groups(key):
        er = g.get('entries-read')
        cmd = ['XGROUP', 'CREATE', key, g['name'], g['last-delivered-id']]
        if er is not None:
            cmd += ['ENTRIESREAD', er]
        d.execute_command(*cmd)
        for c in s.xinfo_consumers(key, g['name']):
            d.execute_command('XGROUP', 'CREATECONSUMER', key, g['name'], c['name'])
        pel = s.xpending_range(key, g['name'], '-', '+', 100000)
        for p in pel:
            deliver_time = now_ms - p['time_since_delivered']
            d.execute_command('XCLAIM', key, g['name'], p['consumer'], 0, p['message_id'],
                              'TIME', deliver_time, 'RETRYCOUNT', p['times_delivered'],
                              'FORCE', 'JUSTID')

for n in (0, 2):
    migrate_db(n)

print("migrated:", stats)
