import redis
mismatches=[]
def cmp_db(n):
    s=redis.Redis(port=6379,db=n,decode_responses=False)
    d=redis.Redis(port=6380,db=n,decode_responses=False)
    for k in s.keys('*'):
        t=s.type(k)
        if t==b'string':
            if s.get(k)!=d.get(k): mismatches.append((n,k,'string'))
        elif t==b'list':
            if s.lrange(k,0,-1)!=d.lrange(k,0,-1): mismatches.append((n,k,'list'))
        elif t==b'set':
            if s.smembers(k)!=d.smembers(k): mismatches.append((n,k,'set'))
        elif t==b'zset':
            if s.zrange(k,0,-1,withscores=True)!=d.zrange(k,0,-1,withscores=True): mismatches.append((n,k,'zset'))
        elif t==b'hash':
            if s.hgetall(k)!=d.hgetall(k): mismatches.append((n,k,'hash'))
        elif t==b'stream':
            if s.xrange(k,'-','+')!=d.xrange(k,'-','+'):
                mismatches.append((n,k,'stream-entries'))
            si=s.xinfo_stream(k); di=d.xinfo_stream(k)
            for f in ('last-generated-id','max-deleted-entry-id','entries-added','length'):
                if si[f]!=di[f]: mismatches.append((n,k,'stream-meta-'+f, si[f], di[f]))
        # TTL check (allow 2s drift)
        st=s.ttl(k); dt=d.ttl(k)
        if st>=0:
            if abs(st-dt)>2: mismatches.append((n,k,'ttl',st,dt))
        else:
            if dt!=-1: mismatches.append((n,k,'ttl-should-be-none',st,dt))
cmp_db(0); cmp_db(2)
print("total mismatches:", len(mismatches))
for m in mismatches[:50]: print(m)
